    // source pixels under an output pixel are counted. Centre carries the
    // full box, the outer clusters carry the negative lobes.
    vec3 c = texture2D(iChannel0, uv + vec2( 0.25,  0.25) * px).rgb
           + texture2D(iChannel0, uv + vec2(-0.25,  0.25) * px).rgb
